changeSet.sql:
CREATE PROCEDURE safe_drop_index(IN tbl VARCHAR(64), IN idx VARCHAR(64))
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.statistics
        WHERE table_schema = DATABASE()
          AND table_name = tbl
          AND index_name = idx
    ) THEN
        SET @s = CONCAT('ALTER TABLE ', tbl, ' DROP INDEX ', idx);
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END IF;
END;

CREATE PROCEDURE safe_drop_fk(IN tbl VARCHAR(64), IN fk VARCHAR(64))
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.table_constraints
        WHERE table_schema = DATABASE()
          AND table_name = tbl
          AND constraint_name = fk
          AND constraint_type = 'FOREIGN KEY'
    ) THEN
        SET @s = CONCAT('ALTER TABLE ', tbl, ' DROP FOREIGN KEY ', fk);
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END IF;
END;

CREATE PROCEDURE safe_drop_column(IN tbl VARCHAR(64), IN col VARCHAR(64))
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = DATABASE()
          AND table_name = tbl
          AND column_name = col
    ) THEN
        SET @s = CONCAT('ALTER TABLE ', tbl, ' DROP COLUMN ', col);
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END IF;
END;

CREATE PROCEDURE safe_drop_table(IN tbl VARCHAR(64))
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = DATABASE()
          AND table_name = tbl
    ) THEN
        SET @s = CONCAT('DROP TABLE ', tbl);
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END IF;
END;

CREATE TABLE IF NOT EXISTS BRAND
(
    ID   CHAR(36)     NOT NULL PRIMARY KEY,
    CODE VARCHAR(64)  NOT NULL UNIQUE,
    NAME VARCHAR(255) NOT NULL
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE USER_LOGIN_HISTORY
    ADD COLUMN IF NOT EXISTS BRAND_ID CHAR (36),
    ADD COLUMN IF NOT EXISTS BRAND_NAME VARCHAR (255);

ALTER TABLE USER_POST
    ADD COLUMN IF NOT EXISTS MARK_BRAND_ID CHAR (36),
    ADD CONSTRAINT FK_USER_POST_BRAND FOREIGN KEY (MARK_BRAND_ID) REFERENCES BRAND(ID);

ALTER TABLE IMPORT_USERS_DATA
    ADD COLUMN IF NOT EXISTS MARK_BRAND_ID CHAR (36),
    ADD CONSTRAINT FK_IMPORT_USERS_DATA_BRAND FOREIGN KEY (MARK_BRAND_ID) REFERENCES BRAND(ID);

DROP PROCEDURE IF EXISTS safe_drop_index;
DROP PROCEDURE IF EXISTS safe_drop_fk;
DROP PROCEDURE IF EXISTS safe_drop_column;
DROP PROCEDURE IF EXISTS safe_drop_table;
